mapper.select:
select t.detail_type,t.detail_type detailType,t.cur_degrees,t.cur_degrees curDegrees,t.machine_id,t.machine_id
machineId,t.prestore_degrees,t.prestore_degrees prestoreDegrees,t.detail_id,t.detail_id
detailId,t.remark,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id
communityId,t.cur_reading_time,t.cur_reading_time curReadingTime,t.state
from meter_machine_detail t
where 1 =1

    and t.detail_type= #{detailType}


    and t.cur_degrees= #{curDegrees}


    and t.machine_id= #{machineId}


    and t.prestore_degrees= #{prestoreDegrees}


    and t.detail_id= #{detailId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.cur_reading_time= #{curReadingTime}


    and t.state= #{state}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update meter_machine_detail t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.detail_type= #{detailType}


    , t.cur_degrees= #{curDegrees}


    , t.prestore_degrees= #{prestoreDegrees}


    , t.state= #{state}


    , t.remark= #{remark}


    , t.cur_reading_time= #{curReadingTime}

where 1=1

    and t.detail_id= #{detailId}


    and t.community_id= #{communityId}


    and t.machine_id= #{machineId}

mapper.select:
select count(1) count
from meter_machine_detail t
where 1 =1

    and t.detail_type= #{detailType}


    and t.cur_degrees= #{curDegrees}


    and t.machine_id= #{machineId}


    and t.prestore_degrees= #{prestoreDegrees}


    and t.detail_id= #{detailId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.cur_reading_time= #{curReadingTime}


    and t.state= #{state}

select count(1) count
from meter_machine_detail mmd
left join meter_machine mm on mmd.machine_id = mm.machine_id and mm.status_cd = '0'
left join meter_type mt on mm.meter_type = mt.type_id and mt.status_cd = '0'
where mmd.status_cd = '0'

    and mmd.detail_type= #{detailType}


    and mmd.cur_degrees= #{curDegrees}


    and mmd.machine_id= #{machineId}


    and mmd.prestore_degrees= #{prestoreDegrees}


    and mmd.detail_id= #{detailId}


    and mmd.remark= #{remark}


    and mmd.status_cd= #{statusCd}


    and mmd.community_id= #{communityId}


    and mm.room_id= #{roomId}


    and mmd.cur_reading_time= #{curReadingTime}


    and mmd.state= #{state}


    and mm.machine_name like concat('%', #{machineNameLike}, '%')


    and mm.address like concat('%', #{addressLike}, '%')


    and mm.room_name like concat('%', #{roomNameLike}, '%')

select mmd.detail_id, mmd.detail_id detailId,
       mmd.machine_id, mmd.machine_id machineId,
       mmd.detail_type, mmd.detail_type detailType,
       mmd.prestore_degrees, mmd.prestore_degrees prestoreDegrees,
       mmd.cur_degrees, mmd.cur_degrees curDegrees,
       mmd.cur_reading_time, mmd.cur_reading_time curReadingTime,
       mmd.community_id, mmd.community_id communityId, mmd.remark,
       mmd.create_time, mmd.create_time createTime,
       mmd.status_cd, mmd.status_cd statusCd, mmd.state,
       mm.machine_name, mm.machine_name machineName, mm.address,
       mm.room_name, mm.room_name roomName,
       mm.room_id, mm.room_id roomId,
       mt.type_name, mt.type_name typeName,
       mt.type_id, mt.type_id typeId
from meter_machine_detail mmd
left join meter_machine mm on mmd.machine_id = mm.machine_id and mm.status_cd = '0'
left join meter_type mt on mm.meter_type = mt.type_id and mt.status_cd = '0'
where mmd.status_cd = '0'

    and mmd.detail_type= #{detailType}


    and mmd.cur_degrees= #{curDegrees}


    and mmd.machine_id= #{machineId}


    and mmd.prestore_degrees= #{prestoreDegrees}


    and mmd.detail_id= #{detailId}


    and mmd.remark= #{remark}


    and mmd.status_cd= #{statusCd}


    and mmd.community_id= #{communityId}


    and mm.room_id= #{roomId}


    and mmd.cur_reading_time= #{curReadingTime}


    and mmd.state= #{state}


    and mm.machine_name like concat('%', #{machineNameLike}, '%')


    and mm.address like concat('%', #{addressLike}, '%')


    and mm.room_name like concat('%', #{roomNameLike}, '%')

order by mmd.create_time desc, mm.room_name, mm.meter_type, mm.address

    limit #{page}, #{row}

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from meter_machine_charge t
left join meter_machine mm on t.machine_id = mm.machine_id and mm.status_cd = '0'
where 1=1

    and t.community_id= #{communityId}


    and mm.meter_type = #{meterType}

and t.create_time > #{startTime}
group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,sum(t.charge_money) totalCount
from meter_machine_charge t
left join meter_machine mm on t.machine_id = mm.machine_id and mm.status_cd = '0'
where 1=1

    and t.community_id= #{communityId}


    and mm.meter_type = #{meterType}

and t.create_time > #{startTime}
group by DATE_FORMAT(t.create_time,'%Y-%m-%d')
